\"\"\"Send private text prompts to OpenAI's Responses API using only the standard library.

Official OpenAI documentation (Responses API):
https://platform.openai.com/docs/api-reference/responses
https://developers.openai.com/api/docs/guides/migrate-to-responses

Prompts are sent over HTTPS and are not stored for later retrieval ("'`store=false`).
The prompt and API key are never written to disk or logged by this module.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping, MutableMapping, Optional, Sequence, Union

RESPONSES_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o"
DEFAULT_TIMEOUT = 60.0


class OpenAIAPIError(RuntimeError):
    """Raised when the Responses API returns a non-success status."""

    def __init__(
        self,
        message: str,
        *,
        status: Optional[int] = None,
        payload: Any = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.payload = payload


def _api_key(explicit: Optional[str] = None) -> str:
    key = explicit if explicit is not None else os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIAPIError(
            "Missing OpenAI API key. Set OPENAI_API_KEY or pass api_key=..."
        )
    return key


def _request(
    payload: Mapping[str, Any],
    *,
    api_key: [REDACTED_SECRET] = None,
    timeout: float = DEFAULT_TIMEOUT,
) -> dict[str, Any]:
    body = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        RESPONSES_URL,
        data=body,
        method="POST",
        headers={
            "Authorization": "Bearer %s" % _api_key(api_key),
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read().decode("utf-8")
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode("utf-8", errors="replace")
        parsed: Any
        try:
            parsed = json.loads(error_body) if error_body else None
        except json.JSONDecodeError:
            parsed = error_body
        detail = ""
        if isinstance(parsed, dict):
            err = parsed.get("error")
            if isinstance(err, dict):
                detail = str(err.get("message") or "")
            elif isinstance(err, str):
                detail = err
        message = "Responses API request failed with HTTP %s" % exc.code
        if detail:
            message = "%s: %s" % (message, detail)
        raise OpenAIAPIError(message, status=exc.code, payload=parsed) from None
    except urllib.error.URLError as exc:
        raise OpenAIAPIError("Responses API request failed: %s" % exc.reason) from None

    try:
        decoded = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise OpenAIAPIError("Responses API returned invalid JSON") from exc
    if not isinstance(decoded, dict):
        raise OpenAIAPIError("Responses API returned a non-object JSON payload")
    return decoded


def send_private_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: [REDACTED_SECRET] = None,
    instructions: Optional[str] = None,
    timeout: float = DEFAULT_TIMEOUT,
    extra: Optional[Mapping[str, Any]] = None,
) -> dict[str, Any]:
    """Send a private text prompt to ``POST /v1/responses``.

    ``store`` is forced to ``False`` so the response is not retained for later
    retrieval via the API. Callers may pass additional Responses parameters
    through ``extra`` (for example ``max_output_tokens``), but ``store`` cannot
    be overridden.

    Returns the decoded JSON object from the Responses API.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")

    payload: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": False,
    }
    if instructions:
        payload["instructions"] = instructions
    if extra:
        for key, value in extra.items():
            if key == "store":
                continue
            payload[key] = value
    return _request(payload, api_key=[REDACTED_SECRET] timeout=timeout)


def output_text(response: Mapping[str, Any]) -> str:
    """Extract assistant text from a Responses API JSON object."""
    direct = response.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    chunks: list[str] = []
    output = response.get("output")
    if isinstance(output, Sequence):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            content = item.get("content")
            if not isinstance(content, Sequence):
                continue
            for part in content:
                if not isinstance(part, Mapping):
                    continue
                if part.get("type") in {"output_text", "text"}:
                    text = part.get("text")
                    if isinstance(text, str):
                        chunks.append(text)
    return "".join(chunks)


def send_private_text(
    prompt: str,
    **kwargs: Any,
) -> str:
    """Send a private text prompt and return only the assistant'"'s output text.\"\"\"
    return output_text(send_private_prompt(prompt, **kwargs))


class OpenAIClient:
    \"\"\"Small convenience wrapper around :func:"'`send_private_prompt`."""

    def __init__(
        self,
        *,
        api_key: [REDACTED_SECRET] = None,
        model: str = DEFAULT_MODEL,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> None:
        self.api_key = api_key
        self.model = model
        self.timeout = timeout

    def send_private_prompt(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        extra: Optional[Mapping[str, Any]] = None,
    ) -> dict[str, Any]:
        return send_private_prompt(
            prompt,
            model=self.model if model is None else model,
            api_key=[REDACTED_SECRET]
            instructions=instructions,
            timeout=self.timeout,
            extra=extra,
        )

    def send_private_text(self, prompt: str, **kwargs: Any) -> str:
        return output_text(self.send_private_prompt(prompt, **kwargs))


__all__ = [
    "DEFAULT_MODEL",
    "DEFAULT_TIMEOUT",
    "OpenAIAPIError",
    "OpenAIClient",
    "RESPONSES_URL",
    "output_text",
    "send_private_prompt",
    "send_private_text",
]
